\[\mathbb{E}_{x_1,\ldots,x_n} \abs{\sum_{i=1}^n f(x_i)}^{2m} \leq (8mn)^{m}.\]

\label{lots_of_diagonals}


Let $A\subseteq G$ and $k\geq 1$ and $L\subseteq A^k$. Then there exists some $\tup{a}\in L$ such that
\[\#\{ t\in G : \tup{a}+(t,\ldots,t)\in L\}\geq \frac{\lvert L\rvert}{\lvert A+S\rvert^k}\lvert S\rvert.\]

\label{bohr-reg-def}



We say $\nu:\widehat{G}\to \mathbb{R}$ is regular if, with $d=\mathrm{rk}(\nu)$, for all $\kappa\in\mathbb{R}$ with $\abs{\kappa}\leq 1/100d$ we have
\[(1-100 d\abs{\kappa})\leq \frac{\abs{\mathrm{Bohr}((1+\kappa)\nu)}}{\abs{\mathrm{Bohr}(\nu)}}\leq(1+ 100 d\abs{\kappa})\]

\label{reg-conv}

If $B$ is a regular Bohr set of rank $d$ and $\mu:G\to\mathbb{R}_{\geq 0}$ is supported on $B_\rho$, with $\rho \in (0,1)$, then
\[ \norm{ \mu_B*\mu - \mu_B }_{1} \ll \rho d\norm{\mu}_1. \]

\label{bohr-majorise}

There is a constant $c>0$ such that the following holds.  Let $B$ be a regular Bohr set of rank $d$ and $L\geq 1$ be any integer. If $\nu:G\to\mathbb{R}_{\geq 0}$ is supported on $L B_\rho$, where $\rho \leq c/Ld$, and $\norm{\nu}_1=1$, then
\[\mu_B \leq 2\mu_{B_{1+L\rho}}\ast \nu.\]

\label{bourgain-trick}

There is a constant $c>0$ such that the following holds. Let $B$ be a regular Bohr set of rank $d$, suppose $A\subseteq B$ has density $\alpha$, let $\epsilon>0$, and suppose $B',B''\subseteq B_\rho$ where $\rho\leq c\alpha\epsilon/d$. Then either
\begin{enumerate}
\item there is some translate $A'$ of $A$ such that $\abs{A'\cap B'}\geq (1-\epsilon)\alpha\abs{B'}$ and $\abs{A'\cap B''}\geq (1-\epsilon)\alpha \abs{B''}$, or
\item $\norm{\ind{A}\ast \mu_{B'}}_\infty\geq (1+\epsilon/2)\alpha$, or
\item $\norm{\ind{A}\ast \mu_{B''}}_\infty \geq (1+\epsilon/2)\alpha$.
\end{enumerate}

\label{dissociated}


We say that $A\subseteq G$ is dissociated if, for any $m\geq 1$, and any $x\in G$, there is at most one $A'\subset A$ of size $\abs{A'}=m$ such that
\[\sum_{a\in A'}a=x.\]

\label{large_spec}



Let $G$ be a finite abelian group and $f:G\to\mathbb{C}$. Let $\eta\in \mathbb{R}$. The $\eta$-large spectrum is defined to be
\[\Delta_\eta(f) = \{ \gamma\in\widehat{G} : \lvert \widehat{f}(\gamma)\rvert \geq \eta\norm{f}_1\}.\]

\label{general_hoelder}



Let $G$ be a finite abelian group and $f:G\to\mathbb{C}$. Let $\nu:G\to \mathbb{R}_{\geq 0}$ be such that whenever $\abs{f}\neq 0$ we have $\nu \geq 1$. Let $\Delta\subseteq \Delta_\eta(f)$. Then, for any $m\geq 1$.
\[\eta^{2m}\frac{\norm{f}_1^2}{\norm{f}_2^2}\abs{\Delta}^{2m}\le E_{2m}(\Delta;\nu).\]

\label{spec_hoelder}



Let $G$ be a finite abelian group and $f:G\to\mathbb{C}$. Let $\Delta\subseteq \Delta_\eta(f)$. Then, for any $m\geq 1$.
\[N^{-1}\eta^{2m}\frac{\norm{f}_1^2}{\norm{f}_2^2}\abs{\Delta}^{2m}\le E_{2m}(\Delta).\]

