\label{ast_le_circ}


For any function $f:G\to \mathbb{C}$ and integer $k\geq 1$
\[\| f\ast f\|_{2k}\leq \| f\circ f\|_{2k}.\]

\label{ast_expand}


For any function $f$ with $\sum f(x)=1$
\[f\ast f-1/N = (f-1/N)\ast (f-1/N).\]

\label{circ_expand}


For any function $f$ with $\sum f(x)=1$
\[f\circ f-1/N = (f-1/N)\circ (f-1/N).\]

\label{no3aps_inner_prod}



If $A\subseteq G$ has no non-trivial three-term arithmetic progressions and $G$ has odd order then
\[\langle \mu_A\ast \mu_A,\mu_{2\cdot A}\rangle = 1/\abs{A}^2.\]

\label{ff}




Let $q$ be an odd prime power. If $A\subseteq \mathbb{F}_q^n$ with $\alpha=\abs{A}/q^n$ has no non-trivial three-term arithmetic progressions then
\[n \ll \lo(\alpha)^9.\]

\label{pos-def-measures}

There is a constant $c>0$ such that the following holds. Let $p \geq 2$ be an even integer. Let $f : G \to \mathbb{R}$, let $B \subseteq G$ and $B', B'' \subseteq B_{c/\mathrm{rank}(B)}$ all be regular Bohr sets. Then
\[ \norm{ f\circ f }_{p(\mu_{B'}\circ \mu_{B'}\ast \mu_{B''}\circ \mu_{B''})} \geq \tfrac{1}{2} \norm{f*f}_{p(\mu_B)}. \]

\label{hoelder-lifting}

There is a constant $c>0$ such that the following holds. Let $\epsilon >0$. Let $B \subseteq G$ be a regular Bohr set and $A\subseteq B$ with relative density $\alpha$, and let $B' \subseteq B_{c\epsilon\alpha/\mathrm{rank}(B)}$ be a regular Bohr set and $C\subseteq B'$ with relative density $\gamma$. Either
\begin{enumerate}
\item $\abs{ \langle \mu_A*\mu_A, \mu_{C} \rangle - \mu(B)^{-1} } \leq \epsilon \mu(B)^{-1}$ or
\item there is some $p \ll\lo{\gamma}$ such that $\norm{ (\mu_A-\mu_B)*(\mu_A-\mu_B)}_{p(\mu_{B'})} \geq \tfrac{1}{2}\epsilon \mu(B)^{-1}$.
\end{enumerate}

\label{int}



If $A\subseteq \{1,\ldots,N\}$ contains no non-trivial three-term arithmetic progressions then
\[\lvert A\rvert \leq \frac{N}{\exp(-c(\log N)^{1/12})}\]

\label{nonneg_moments}


For any function $f:G\to\mathbb{R}$ and integer $k\geq 0$
